15	export async function GET() {
16	  const authUser = await getAuthenticatedUser()
17	  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
18	  if (!['owner', 'admin'].includes(authUser.role)) {
19	    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
20	  }
21	
22	  const { success } = await authedRatelimit.limit(authUser.user.id)
23	  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
24	
25	  const supabase = await createClient()
26	
27	  try {
28	    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
29	  } catch (err) {
30	    if (err instanceof FeatureGateError) {
31	      return NextResponse.json({ error: 'Referral program requires Studio plan' }, { status: 403 })
32	    }
33	    throw err
34	  }
35	
36	  try {
37	    const { data, error } = await supabase
38	      .from('referral_codes')
39	      .select(`
40	        id, code, discount_type, discount_value, referrer_reward_type, referrer_reward_value,
41	        max_uses, uses_count, is_active, expires_at, created_at,
42	        client:clients(id, first_name, last_name, email)
43	      `)
44	      .eq('studio_id', authUser.studioId)
45	      .order('created_at', { ascending: false })
46	
47	    if (error) {
48	      logger.error({ err: error, studioId: authUser.studioId }, 'referral codes GET failed')
49	      return NextResponse.json({ error: 'Failed to fetch referral codes' }, { status: 500 })
50	    }
51	
52	    return NextResponse.json({ data: data ?? [] })
53	  } catch (err) {
54	    logger.error({ err }, 'referral codes GET unexpected error')
55	    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
56	  }
57	}
