60	  const authUser = await getAuthenticatedUser()
61	  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
62	
63	  const { success } = await authedRatelimit.limit(authUser.user.id)
64	  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })
65	
66	  let body: unknown
67	  try { body = await request.json() } catch {
68	    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
