70	
71	  const parsed = GenerateCodeSchema.safeParse(body)
72	  if (!parsed.success) {
73	    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
74	  }
75	
76	  const supabase = await createClient()
77	
78	  try {
79	    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
