86	
87	  try {
88	    const { data, error } = await supabase.rpc('generate_referral_code', {
89	      p_studio_id: authUser.studioId,
90	      p_client_id: parsed.data.client_id,
91	      p_discount_type: parsed.data.discount_type,
92	      p_discount_value: parsed.data.discount_value,
93	    })
94	
95	    if (error) {
96	      logger.error({ err: error }, 'generate_referral_code rpc failed')
97	      return NextResponse.json({ error: 'Failed to generate referral code' }, { status: 500 })
98	    }
99	
100	    return NextResponse.json({ data })
101	  } catch (err) {
