'use client'

import { useState } from 'react'
import { toast } from 'sonner'
import { AlertTriangle } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Label } from '@/components/ui/label'
import { Input } from '@/components/ui/input'
import { Switch } from '@/components/ui/switch'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'

type ReferrerRewardType = 'credit' | 'percentage' | 'free_session' | 'none'
type ReferredRewardType = 'discount_fixed' | 'discount_percent' | 'none'
type ProgramTrigger = 'booking_completed' | 'first_booking' | 'payment_settled'

export interface ReferralProgramData {
  referrer_reward_type: ReferrerRewardType | null
  referrer_reward_value: number | null
  referred_reward_type: ReferredRewardType | null
  referred_reward_value: number | null
  trigger: ProgramTrigger
  expiry_days: number
  is_active: boolean
}

interface ReferralProgramCardProps {
  initialData: ReferralProgramData | null
  onSaved: (data: ReferralProgramData) => void
}

const REFERRER_REWARD_LABELS: Record<ReferrerRewardType, string> = {
  credit: 'Store credit ($)',
  percentage: 'Discount percentage (%)',
  free_session: 'Free session',
  none: 'No reward',
}

const REFERRED_REWARD_LABELS: Record<ReferredRewardType, string> = {
  discount_fixed: 'Fixed discount ($)',
  discount_percent: 'Discount percentage (%)',
  none: 'No reward',
}

const TRIGGER_LABELS: Record<ProgramTrigger, string> = {
  booking_completed: 'Booking completed',
  first_booking: 'First booking',
  payment_settled: 'Payment settled',
}

function defaultForm(data: ReferralProgramData | null): {
  referrer_reward_type: ReferrerRewardType
  referrer_reward_value: string
  referred_reward_type: ReferredRewardType
  referred_reward_value: string
  trigger: ProgramTrigger
  expiry_days: string
  is_active: boolean
} {
  return {
    referrer_reward_type: data?.referrer_reward_type ?? 'credit',
    referrer_reward_value: String(data?.referrer_reward_value ?? ''),
    referred_reward_type: data?.referred_reward_type ?? 'discount_fixed',
    referred_reward_value: String(data?.referred_reward_value ?? ''),
    trigger: data?.trigger ?? 'booking_completed',
    expiry_days: String(data?.expiry_days ?? 90),
    is_active: data?.is_active ?? false,
  }
}

export function ReferralProgramCard({
  initialData,
  onSaved,
}: ReferralProgramCardProps) {
  const [form, setForm] = useState(() => defaultForm(initialData))
  const [saving, setSaving] = useState(false)

  const isProgramInactive = !form.is_active
  const isUnsaved = initialData === null

  const referrerNeedsValue =
    form.referrer_reward_type !== 'none' &&
    form.referrer_reward_type !== 'free_session'
  const referredNeedsValue = form.referred_reward_type !== 'none'

  async function handleSave() {
    setSaving(true)
    try {
      const body = {
        referrer_reward_type: form.referrer_reward_type,
        referrer_reward_value: referrerNeedsValue
          ? parseFloat(form.referrer_reward_value) || 0
          : null,
        referred_reward_type: form.referred_reward_type,
        referred_reward_value: referredNeedsValue
          ? parseFloat(form.referred_reward_value) || 0
          : null,
        trigger: form.trigger,
        expiry_days: parseInt(form.expiry_days, 10) || 90,
        is_active: form.is_active,
      }

      const res = await fetch('/api/marketing/referrals/program', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
      })

      if (!res.ok) {
        const raw: unknown = await res.json()
        const msg =
          raw &&
          typeof raw === 'object' &&
          'error' in raw &&
          typeof (raw as { error: unknown }).error === 'string'
            ? (raw as { error: string }).error
            : 'Failed to save program'
        throw new Error(msg)
      }

      const json: unknown = await res.json()
      const saved =
        json && typeof json === 'object' && 'data' in json
          ? (json as { data: ReferralProgramData }).data
          : (body as ReferralProgramData)

      toast.success('Program rules saved')
      onSaved(saved)
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to save program')
    } finally {
      setSaving(false)
    }
  }

  return (
    <Card className="shadow-card rounded-xl">
      <CardHeader className="pb-4">
        <CardTitle className="text-sm font-semibold text-foreground">
          Program rules
        </CardTitle>
        <p className="text-xs text-muted-foreground mt-0.5">
          Configure rewards for referrers and new clients. Activate to enable
          code generation.
        </p>
      </CardHeader>

      <CardContent className="space-y-5">
        {/* Inactive / unsaved warning banner */}
        {(isProgramInactive || isUnsaved) && (
          <div className="flex items-start gap-2 rounded-lg border border-border bg-destructive/5 px-3 py-2.5">
            <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0 text-destructive" aria-hidden="true" />
            <p className="text-xs text-destructive">
              {isUnsaved
                ? 'Program inactive — codes can\'t be generated. Set up your program first.'
                : 'Program inactive — codes can\'t be generated. Toggle active below.'}
            </p>
          </div>
        )}

        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
          {/* Referrer reward type */}
          <div className="space-y-1.5">
            <Label className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
              Referrer reward
            </Label>
            <Select
              value={form.referrer_reward_type}
              onValueChange={(v) =>
                setForm((f) => ({
                  ...f,
                  referrer_reward_type: v as ReferrerRewardType,
                }))
              }
            >
              <SelectTrigger className="h-8 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {(Object.keys(REFERRER_REWARD_LABELS) as ReferrerRewardType[]).map(
                  (k) => (
                    <SelectItem key={k} value={k} className="text-xs">
                      {REFERRER_REWARD_LABELS[k]}
                    </SelectItem>
                  )
                )}
              </SelectContent>
            </Select>
            {referrerNeedsValue && (
              <Input
                type="number"
                min={0}
                step={form.referrer_reward_type === 'percentage' ? 1 : 0.01}
                placeholder={
                  form.referrer_reward_type === 'percentage' ? '10' : '25'
                }
                value={form.referrer_reward_value}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    referrer_reward_value: e.target.value,
                  }))
                }
                className="h-8 text-xs font-variant-numeric tabular-nums"
              />
            )}
          </div>

          {/* Referred (new client) reward type */}
          <div className="space-y-1.5">
            <Label className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
              New-client reward
            </Label>
            <Select
              value={form.referred_reward_type}
              onValueChange={(v) =>
                setForm((f) => ({
                  ...f,
                  referred_reward_type: v as ReferredRewardType,
                }))
              }
            >
              <SelectTrigger className="h-8 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {(Object.keys(REFERRED_REWARD_LABELS) as ReferredRewardType[]).map(
                  (k) => (
                    <SelectItem key={k} value={k} className="text-xs">
                      {REFERRED_REWARD_LABELS[k]}
                    </SelectItem>
                  )
                )}
              </SelectContent>
            </Select>
            {referredNeedsValue && (
              <Input
                type="number"
                min={0}
                step={form.referred_reward_type === 'discount_percent' ? 1 : 0.01}
                placeholder={
                  form.referred_reward_type === 'discount_percent' ? '15' : '25'
                }
                value={form.referred_reward_value}
                onChange={(e) =>
                  setForm((f) => ({
                    ...f,
                    referred_reward_value: e.target.value,
                  }))
                }
                className="h-8 text-xs font-variant-numeric tabular-nums"
              />
            )}
          </div>

          {/* Trigger */}
          <div className="space-y-1.5">
            <Label className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
              Trigger
            </Label>
            <Select
              value={form.trigger}
              onValueChange={(v) =>
                setForm((f) => ({ ...f, trigger: v as ProgramTrigger }))
              }
            >
              <SelectTrigger className="h-8 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {(Object.keys(TRIGGER_LABELS) as ProgramTrigger[]).map((k) => (
                  <SelectItem key={k} value={k} className="text-xs">
                    {TRIGGER_LABELS[k]}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Expiry days */}
          <div className="space-y-1.5">
            <Label className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
              Code expiry (days)
            </Label>
            <Input
              type="number"
              min={1}
              step={1}
              placeholder="90"
              value={form.expiry_days}
              onChange={(e) =>
                setForm((f) => ({ ...f, expiry_days: e.target.value }))
              }
              className="h-8 text-xs font-variant-numeric tabular-nums"
            />
          </div>
        </div>

        {/* Active toggle + save row */}
        <div className="flex items-center justify-between border-t border-border pt-4">
          <div className="flex items-center gap-2.5">
            <Switch
              id="referral-program-active"
              checked={form.is_active}
              onCheckedChange={(v) => setForm((f) => ({ ...f, is_active: v }))}
            />
            <Label
              htmlFor="referral-program-active"
              className="cursor-pointer text-xs text-foreground"
            >
              {form.is_active ? 'Active' : 'Inactive'}
            </Label>
          </div>

          <Button
            size="sm"
            disabled={saving}
            onClick={handleSave}
            className="h-8 text-xs"
          >
            {saving ? 'Saving...' : 'Save program'}
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

import { Card, CardContent, CardHeader } from '@/components/ui/card'
import { createClient } from '@/lib/supabase/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'

export interface TopReferrerEntry {
  client_id: string
  client_name: string
  redemption_count: number
}

interface TopReferrersListProps {
  entries: TopReferrerEntry[]
}

export function TopReferrersList({ entries }: TopReferrersListProps) {
  return (
    <Card className="shadow-card rounded-xl">
      <CardHeader className="pb-3">
        <span className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
          Top referrers · last 90d
        </span>
      </CardHeader>
      <CardContent>
        {entries.length === 0 ? (
          <p className="text-xs text-muted-foreground">
            No referrers yet — generate codes to start tracking.
          </p>
        ) : (
          <ol className="space-y-2">
            {entries.map((entry, i) => (
              <li
                key={entry.client_id}
                className="flex items-center justify-between gap-3"
              >
                <div className="flex items-center gap-2 min-w-0">
                  <span className="text-[11px] font-bold tabular-nums text-muted-foreground w-4 shrink-0">
                    {i + 1}
                  </span>
                  <span className="text-xs text-foreground truncate">
                    {entry.client_name}
                  </span>
                </div>
                <span className="text-xs font-semibold tabular-nums text-foreground shrink-0">
                  {entry.redemption_count}
                </span>
              </li>
            ))}
          </ol>
        )}
      </CardContent>
    </Card>
  )
}

/**
 * Server-side data fetcher. Exported separately so callers can await it
 * independently (used by ReferralDashboard server wrapper).
 */
export async function fetchTopReferrers(): Promise<TopReferrerEntry[]> {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return []

  const supabase = await createClient()
  const cutoff = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()

  const { data, error } = await supabase
    .from('referral_redemptions')
    .select('referrer_client_id, client:clients!referral_redemptions_referrer_client_id_fkey(first_name, last_name)')
    .eq('studio_id', authUser.studioId)
    .gte('created_at', cutoff)

  if (error || !data) return []

  // Aggregate in TS (avoids complex RPC dependency; data set is small)
  const counts = new Map<string, { name: string; count: number }>()
  for (const row of data) {
    const id = row.referrer_client_id
    const clientRaw = row.client
    // Supabase join returns single object or null for 1:1 FK
    const clientObj =
      clientRaw && typeof clientRaw === 'object' && !Array.isArray(clientRaw)
        ? (clientRaw as { first_name: string; last_name: string })
        : null
    const name = clientObj
      ? `${clientObj.first_name} ${clientObj.last_name}`.trim()
      : 'Unknown'
    const existing = counts.get(id)
    if (existing) {
      existing.count += 1
    } else {
      counts.set(id, { name, count: 1 })
    }
  }

  return Array.from(counts.entries())
    .sort((a, b) => b[1].count - a[1].count)
    .slice(0, 5)
    .map(([client_id, { name, count }]) => ({
      client_id,
      client_name: name,
      redemption_count: count,
    }))
}

'use client'

import { useState, useEffect, useTransition } from 'react'
import { useRouter } from 'next/navigation'
import { toast } from 'sonner'
import { Clipboard, MessageSquare, Loader2 } from 'lucide-react'
import { Button } from '@/components/ui/button'

// TODO (M6+): Wire actual SMS sending via Twilio when provider is configured.
const SMS_WIRED = false

interface TodayClientsResponse {
  count: number
  client_ids: string[]
}

interface BulkGeneratedCode {
  client_id: string
  code_id: string
  code: string
  share_url: string
  expires_at: string
  client_name?: string
}

interface BulkGenerateForTodayProps {
  programActive: boolean
}

export function BulkGenerateForToday({ programActive }: BulkGenerateForTodayProps) {
  const router = useRouter()
  const [, startTransition] = useTransition()

  const [loading, setLoading] = useState(true)
  const [todayCount, setTodayCount] = useState(0)
  const [todayClientIds, setTodayClientIds] = useState<string[]>([])
  const [generating, setGenerating] = useState(false)
  const [generatedCodes, setGeneratedCodes] = useState<BulkGeneratedCode[]>([])
  const [copied, setCopied] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    async function load() {
      try {
        const res = await fetch('/api/marketing/referrals/today-clients')
        if (!res.ok) return
        const json: unknown = await res.json()
        if (
          json &&
          typeof json === 'object' &&
          'data' in json &&
          json.data &&
          typeof json.data === 'object' &&
          'count' in json.data &&
          'client_ids' in json.data
        ) {
          const d = (json as { data: TodayClientsResponse }).data
          if (!cancelled) {
            setTodayCount(d.count)
            setTodayClientIds(d.client_ids)
          }
        }
      } catch {
        // Non-critical — button stays disabled
      } finally {
        if (!cancelled) setLoading(false)
      }
    }
    void load()
    return () => { cancelled = true }
  }, [])

  async function handleBulkGenerate() {
    if (todayClientIds.length === 0) return
    setGenerating(true)
    try {
      const res = await fetch('/api/marketing/referrals/codes/bulk', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_ids: todayClientIds }),
      })

      if (!res.ok) {
        const raw: unknown = await res.json()
        const msg =
          raw &&
          typeof raw === 'object' &&
          'error' in raw &&
          typeof (raw as { error: unknown }).error === 'string'
            ? (raw as { error: string }).error
            : `Request failed: ${res.status}`
        throw new Error(msg)
      }

      const json: unknown = await res.json()
      const codes =
        json &&
        typeof json === 'object' &&
        'data' in json &&
        Array.isArray((json as { data: unknown }).data)
          ? ((json as { data: BulkGeneratedCode[] }).data)
          : []

      setGeneratedCodes(codes)
      toast.success(`Generated ${codes.length} referral code${codes.length !== 1 ? 's' : ''}`)
      startTransition(() => router.refresh())
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err))
    } finally {
      setGenerating(false)
    }
  }

  async function handleCopy(text: string) {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(text)
      setTimeout(() => setCopied(null), 1500)
    } catch {
      toast.error('Failed to copy to clipboard')
    }
  }

  const isDisabled = !programActive || loading || todayCount === 0 || generating

  return (
    <div className="space-y-3">
      <div className="flex items-center gap-3">
        <Button
          size="sm"
          disabled={isDisabled}
          onClick={handleBulkGenerate}
          className="h-9"
          aria-label={`Generate referral codes for today's ${todayCount} client${todayCount !== 1 ? 's' : ''}`}
        >
          {generating && <Loader2 className="mr-1.5 h-3.5 w-3.5 animate-spin" aria-hidden="true" />}
          {loading
            ? 'Loading...'
            : `Generate codes for today's clients (${todayCount})`}
        </Button>

        {!programActive && (
          <span className="text-xs text-muted-foreground">
            Set up your program first →
          </span>
        )}
        {programActive && !loading && todayCount === 0 && (
          <span className="text-xs text-muted-foreground">
            No clients booked today.
          </span>
        )}
      </div>

      {/* Inline results */}
      {generatedCodes.length > 0 && (
        <ul className="space-y-2 rounded-xl border border-border p-3">
          {generatedCodes.map((entry) => (
            <li
              key={entry.code_id}
              className="flex items-center justify-between gap-3"
            >
              <div className="min-w-0">
                {entry.client_name && (
                  <p className="text-xs text-muted-foreground truncate mb-0.5">
                    {entry.client_name}
                  </p>
                )}
                <code className="text-sm font-mono font-semibold tracking-wider">
                  {entry.code}
                </code>
              </div>
              <div className="flex items-center gap-1.5 shrink-0">
                <button
                  type="button"
                  onClick={() => handleCopy(entry.share_url)}
                  className="flex items-center gap-1 rounded px-2 py-1 text-[11px] text-muted-foreground hover:text-foreground hover:bg-accent transition-colors"
                  aria-label={`Copy share link for code ${entry.code}`}
                >
                  <Clipboard className="h-3.5 w-3.5" aria-hidden="true" />
                  {copied === entry.share_url ? 'Copied' : 'Copy link'}
                </button>

                {SMS_WIRED && (
                  <button
                    type="button"
                    className="flex items-center gap-1 rounded px-2 py-1 text-[11px] text-muted-foreground hover:text-foreground hover:bg-accent transition-colors"
                    aria-label={`Send code ${entry.code} via SMS`}
                  >
                    <MessageSquare className="h-3.5 w-3.5" aria-hidden="true" />
                    Send SMS
                  </button>
                )}
              </div>
            </li>
          ))}
        </ul>
      )}
    </div>
  )
}

'use client'

import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import { useTransition, useState } from 'react'
import { toast } from 'sonner'
import { cn } from '@/lib/utils'

export type CodeFilter = 'all' | 'active' | 'expired' | 'fully_used'

const FILTER_LABELS: Record<CodeFilter, string> = {
  all: 'All',
  active: 'Active',
  expired: 'Expired',
  fully_used: 'Fully used',
}

const FILTERS: CodeFilter[] = ['all', 'active', 'expired', 'fully_used']

interface CodesListFiltersProps {
  /** IDs of currently displayed codes for multi-select */
  codeIds: string[]
  onDeactivated?: () => void
}

export function CodesListFilters({ codeIds, onDeactivated }: CodesListFiltersProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const [, startTransition] = useTransition()

  const currentFilter = (searchParams.get('codes') as CodeFilter | null) ?? 'all'

  const [selected, setSelected] = useState<Set<string>>(new Set())
  const [deactivating, setDeactivating] = useState(false)

  function setFilter(f: CodeFilter) {
    const params = new URLSearchParams(searchParams.toString())
    if (f === 'all') {
      params.delete('codes')
    } else {
      params.set('codes', f)
    }
    startTransition(() => {
      router.replace(`${pathname}?${params.toString()}`, { scroll: false })
    })
    setSelected(new Set())
  }

  function toggleSelect(id: string) {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(id)) {
        next.delete(id)
      } else {
        next.add(id)
      }
      return next
    })
  }

  function toggleSelectAll() {
    if (selected.size === codeIds.length) {
      setSelected(new Set())
    } else {
      setSelected(new Set(codeIds))
    }
  }

  async function handleBulkDeactivate() {
    if (selected.size === 0) return
    setDeactivating(true)
    try {
      const res = await fetch('/api/marketing/referrals/codes/bulk-deactivate', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code_ids: Array.from(selected) }),
      })

      if (!res.ok) {
        const raw: unknown = await res.json()
        const msg =
          raw &&
          typeof raw === 'object' &&
          'error' in raw &&
          typeof (raw as { error: unknown }).error === 'string'
            ? (raw as { error: string }).error
            : `Request failed: ${res.status}`
        throw new Error(msg)
      }

      toast.success(`Deactivated ${selected.size} code${selected.size !== 1 ? 's' : ''}`)
      setSelected(new Set())
      onDeactivated?.()
      startTransition(() => router.refresh())
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err))
    } finally {
      setDeactivating(false)
    }
  }

  return (
    <div className="space-y-3">
      {/* Filter pills */}
      <div className="flex items-center gap-1.5 flex-wrap">
        {FILTERS.map((f) => (
          <button
            key={f}
            type="button"
            onClick={() => setFilter(f)}
            className={cn(
              'rounded-full border px-3 py-1 text-[11px] font-medium transition-colors',
              currentFilter === f
                ? 'border-foreground bg-foreground text-background'
                : 'border-border bg-transparent text-muted-foreground hover:text-foreground hover:border-foreground/50',
            )}
            aria-pressed={currentFilter === f}
          >
            {FILTER_LABELS[f]}
          </button>
        ))}

        {/* Multi-select controls */}
        {codeIds.length > 0 && (
          <button
            type="button"
            onClick={toggleSelectAll}
            className="ml-2 text-[11px] text-muted-foreground hover:text-foreground underline underline-offset-2 transition-colors"
          >
            {selected.size === codeIds.length ? 'Deselect all' : 'Select all'}
          </button>
        )}

        {selected.size > 0 && (
          <button
            type="button"
            disabled={deactivating}
            onClick={handleBulkDeactivate}
            className="ml-1 rounded border border-destructive/40 bg-destructive/5 px-2.5 py-1 text-[11px] font-medium text-destructive hover:bg-destructive/10 transition-colors disabled:opacity-50"
          >
            {deactivating
              ? 'Deactivating...'
              : `Deactivate ${selected.size} selected`}
          </button>
        )}
      </div>

      {/* Expose toggle for parent rows — only rendered when codeIds are visible */}
      {codeIds.length > 0 && (
        <div className="hidden" aria-hidden="true" data-codes-select-context="true">
          {/* Row-level checkboxes are rendered by the parent list via selectedSet + toggleSelect */}
          {codeIds.map((id) => (
            <input
              key={id}
              type="checkbox"
              data-code-checkbox={id}
              checked={selected.has(id)}
              onChange={() => toggleSelect(id)}
              aria-label={`Select code ${id}`}
            />
          ))}
        </div>
      )}

      {/* Export the selection state through a callback pattern */}
      <_CodesSelectBridge
        codeIds={codeIds}
        selected={selected}
        toggleSelect={toggleSelect}
      />
    </div>
  )
}

/**
 * Internal bridge to expose checkbox state to sibling components via DOM data
 * attributes. This avoids prop-drilling through the server component boundary.
 *
 * For the M5 scope, the parent CodesList uses this component to read selection.
 */
function _CodesSelectBridge({
  codeIds,
  selected,
  toggleSelect,
}: {
  codeIds: string[]
  selected: Set<string>
  toggleSelect: (id: string) => void
}) {
  return (
    <div data-codes-selection={JSON.stringify(Array.from(selected))} className="sr-only" aria-hidden="true">
      {codeIds.map((id) => (
        <button key={id} type="button" onClick={() => toggleSelect(id)} aria-label={`toggle select ${id}`} />
      ))}
    </div>
  )
}

/**
 * Exported hook for parent to apply the active filter to a list of codes.
 */
export function applyCodeFilter<
  T extends {
    is_active: boolean
    expires_at?: string | null
    uses_count: number
    max_uses: number | null
  },
>(codes: T[], filter: CodeFilter): T[] {
  const now = new Date()
  switch (filter) {
    case 'active':
      return codes.filter(
        (c) =>
          c.is_active &&
          (c.expires_at == null || new Date(c.expires_at) > now) &&
          (c.max_uses == null || c.uses_count < c.max_uses),
      )
    case 'expired':
      return codes.filter(
        (c) => c.expires_at != null && new Date(c.expires_at) <= now,
      )
    case 'fully_used':
      return codes.filter(
        (c) => c.max_uses != null && c.uses_count >= c.max_uses,
      )
    case 'all':
    default:
      return codes
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logAuditAction } from '@/lib/audit'
