const PatchProgramSchema = z.object({
  referrer_reward_type: z
    .enum(['credit', 'percentage', 'free_session', 'none'])
    .nullable()
    .optional(),
  referrer_reward_value: z.number().nullable().optional(),
  referred_reward_type: z
    .enum(['discount_fixed', 'discount_percent', 'none'])
    .nullable()
    .optional(),
  referred_reward_value: z.number().nullable().optional(),
  trigger: z
    .enum(['booking_completed', 'first_booking', 'payment_settled'])
    .optional(),
  expiry_days: z.number().int().min(1).optional(),
  is_active: z.boolean().optional(),
})

/** Default program shape returned when no row exists yet. */
function defaultProgram(studioId: string) {
  return {
    studio_id: studioId,
    referrer_reward_type: null,
    referrer_reward_value: null,
    referred_reward_type: null,
    referred_reward_value: null,
    trigger: 'booking_completed' as const,
    expiry_days: 90,
    is_active: false,
    created_at: null,
    updated_at: null,
  }
}

export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    const { data, error } = await supabase
      .from('referral_programs')
      .select('*')
      .eq('studio_id', authUser.studioId)
      .maybeSingle()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'referral_programs GET failed')
      return NextResponse.json({ error: 'Failed to fetch program' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? defaultProgram(authUser.studioId) })
  } catch (err) {
    logger.error({ err }, 'referral_programs GET unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = PatchProgramSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    const upsertData = {
      studio_id: authUser.studioId,
      ...parsed.data,
    }

    const { data, error } = await supabase
      .from('referral_programs')
      .upsert(upsertData, { onConflict: 'studio_id' })
      .select()
      .single()

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'referral_programs PATCH failed')
      return NextResponse.json({ error: 'Failed to save program' }, { status: 500 })
    }

    await logAuditAction(
      authUser.user.authId,
      'referral_program.upsert',
      { type: 'referral_programs', id: authUser.studioId },
      { is_active: parsed.data.is_active ?? null },
      authUser.studioId,
    )

    return NextResponse.json({ data })
  } catch (err) {
    logger.error({ err }, 'referral_programs PATCH unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import { NextResponse } from 'next/server'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

/**
 * GET /api/marketing/referrals/today-clients
 *
 * Returns clients with at least one booking starting today (local date, UTC).
 * Excludes clients who already have an active referral code for this studio.
 */
export async function GET() {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    const todayStart = new Date()
    todayStart.setUTCHours(0, 0, 0, 0)
    const todayEnd = new Date()
    todayEnd.setUTCHours(23, 59, 59, 999)

    // Clients booked today
    const { data: bookingsData, error: bookingsError } = await supabase
      .from('bookings')
      .select('client_id')
      .eq('studio_id', authUser.studioId)
      .gte('scheduled_at', todayStart.toISOString())
      .lte('scheduled_at', todayEnd.toISOString())
      .not('status', 'in', '(cancelled,no_show)')

    if (bookingsError) {
      logger.error({ err: bookingsError }, 'today-clients: bookings query failed')
      return NextResponse.json({ error: 'Failed to fetch today\'s clients' }, { status: 500 })
    }

    if (!bookingsData || bookingsData.length === 0) {
      return NextResponse.json({ data: { count: 0, client_ids: [] } })
    }

    // Unique client IDs from today's bookings
    const uniqueClientIds = [...new Set(bookingsData.map((b) => b.client_id))]

    // Exclude clients who already have an active referral code
    const { data: existingCodes, error: codesError } = await supabase
      .from('referral_codes')
      .select('client_id')
      .eq('studio_id', authUser.studioId)
      .eq('is_active', true)
      .in('client_id', uniqueClientIds)

    if (codesError) {
      logger.error({ err: codesError }, 'today-clients: referral_codes query failed')
      // Non-fatal — return all today's clients without exclusion
      return NextResponse.json({
        data: { count: uniqueClientIds.length, client_ids: uniqueClientIds },
      })
    }

    const alreadyHaveCode = new Set(
      (existingCodes ?? []).map((c) => c.client_id),
    )
    const eligibleIds = uniqueClientIds.filter((id) => !alreadyHaveCode.has(id))

    return NextResponse.json({
      data: { count: eligibleIds.length, client_ids: eligibleIds },
    })
  } catch (err) {
    logger.error({ err }, 'today-clients unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { requireFeatureRpc, FeatureGateError } from '@/lib/billing/feature-gate'
import { logger } from '@/lib/logger'

const BulkGenerateSchema = z.object({
  client_ids: z.array(z.string().uuid()).min(1).max(100),
})

/**
 * POST /api/marketing/referrals/codes/bulk
 *
 * Calls bulk_generate_referral_codes RPC (SECURITY DEFINER, audit-critical).
 * Rate-limited via expensiveRatelimit (heavier operation).
 */
export async function POST(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await expensiveRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = BulkGenerateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    // bulk_generate_referral_codes is SECURITY DEFINER — required per project rules.
    // Direct inserts are forbidden for audit-critical tables.
    const { data, error } = await supabase.rpc('bulk_generate_referral_codes', {
      p_studio_id: authUser.studioId,
      p_client_ids: parsed.data.client_ids,
    })

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'bulk_generate_referral_codes RPC failed')

      // Surface specific errors from the RPC (no_program, program_inactive)
      if (error.message?.includes('no_program')) {
        return NextResponse.json(
          { error: 'No referral program configured. Set up your program first.' },
          { status: 422 },
        )
      }
      if (error.message?.includes('program_inactive')) {
        return NextResponse.json(
          { error: 'Referral program is inactive. Activate it in program settings.' },
          { status: 422 },
        )
      }

      return NextResponse.json({ error: 'Failed to generate referral codes' }, { status: 500 })
    }

    return NextResponse.json({ data: data ?? [] })
  } catch (err) {
    logger.error({ err }, 'referral codes bulk generate unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
