/**
 * PATCH /api/marketing/referrals/codes/bulk-deactivate
 *
 * Sets is_active = false for the given code_ids.
 * RLS ensures only codes belonging to the caller's studio are updated.
 */
export async function PATCH(request: NextRequest) {
  const authUser = await getAuthenticatedUser()
  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })
  if (!['owner', 'admin'].includes(authUser.role)) {
    return NextResponse.json({ error: 'Forbidden' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = BulkDeactivateSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json({ error: parsed.error.flatten() }, { status: 400 })
  }

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    const { data, error } = await supabase
      .from('referral_codes')
      .update({ is_active: false })
      .eq('studio_id', authUser.studioId)
      .in('id', parsed.data.code_ids)
