      return NextResponse.json({ error: 'Failed to deactivate codes' }, { status: 500 })
    }

    const updatedCount = data?.length ?? 0

    await logAuditAction(
      authUser.user.authId,
      'referral_codes.bulk_deactivated',
      { type: 'referral_codes', id: authUser.studioId },
      { code_ids: parsed.data.code_ids, updated_count: updatedCount },
      authUser.studioId,
    )

    return NextResponse.json({ data: { updated_count: updatedCount } })
  } catch (err) {
    logger.error({ err }, 'bulk-deactivate unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

