  if (!authUser) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(authUser.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  const supabase = await createClient()

  try {
    await requireFeatureRpc(supabase, authUser.studioId, 'referral_program')
  } catch (err) {
    if (err instanceof FeatureGateError) {
      return NextResponse.json(
        { error: 'Referral program requires Studio plan' },
        { status: 403 },
      )
    }
    throw err
  }

  try {
    const cutoff = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000).toISOString()

    const { data, error } = await supabase
      .from('referral_redemptions')
      .select(
        'referrer_client_id, client:clients!referral_redemptions_referrer_client_id_fkey(first_name, last_name)',
      )
      .eq('studio_id', authUser.studioId)
      .gte('created_at', cutoff)

    if (error) {
      logger.error({ err: error, studioId: authUser.studioId }, 'top referrers query failed')
      return NextResponse.json({ error: 'Failed to fetch top referrers' }, { status: 500 })
    }

    // Aggregate in-process (result set is small)
    const counts = new Map<string, { name: string; count: number }>()
    for (const row of data ?? []) {
      const id = row.referrer_client_id
      const clientRaw = row.client
      const clientObj =
        clientRaw &&
        typeof clientRaw === 'object' &&
        !Array.isArray(clientRaw)
          ? (clientRaw as { first_name: string; last_name: string })
          : null
      const name = clientObj
        ? `${clientObj.first_name} ${clientObj.last_name}`.trim()
        : 'Unknown'
      const existing = counts.get(id)
      if (existing) {
        existing.count += 1
      } else {
        counts.set(id, { name, count: 1 })
      }
    }

    const top5 = Array.from(counts.entries())
      .sort((a, b) => b[1].count - a[1].count)
      .slice(0, 5)
      .map(([client_id, { name, count }]) => ({
        client_id,
        client_name: name,
        redemption_count: count,
      }))

    return NextResponse.json({ data: top5 })
  } catch (err) {
    logger.error({ err }, 'top referrers unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useState, useTransition, useCallback } from 'react'
import { useRouter, useSearchParams } from 'next/navigation'
import { toast } from 'sonner'
import { Gift, Copy, Check, Plus, Clipboard, MessageSquare } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible'
import { EmptyState } from '@/components/shared/EmptyState'
import { KpiCard } from '@/components/shared/KpiCard'
import {
  ReferralProgramCard,
  type ReferralProgramData,
} from './ReferralProgramCard'
import { BulkGenerateForToday } from './BulkGenerateForToday'
import { TopReferrersList, type TopReferrerEntry } from './TopReferrersList'
import { CodesListFilters, applyCodeFilter, type CodeFilter } from './CodesListFilters'

// TODO (M6+): Wire actual SMS sending via Twilio when provider is configured.
const SMS_WIRED = false

interface ReferralCodeRow {
  id: string
  code: string
  discount_type: 'percentage' | 'fixed'
  discount_value: number
  uses_count: number
  max_uses: number | null
  is_active: boolean
  expires_at?: string | null
  client: { id: string; first_name: string; last_name: string; email: string } | null
}

interface ClientOption {
  id: string
  display: string
}

interface ReferralDashboardProps {
  codes: ReferralCodeRow[]
  totalReferrals: number
  totalRedemptions: number
  topReferrers: TopReferrerEntry[]
  clientOptions: ClientOption[]
  canManage: boolean
  initialProgram: ReferralProgramData | null
}

export function ReferralDashboard({
  codes,
  totalReferrals,
  totalRedemptions,
  topReferrers,
  clientOptions,
  canManage,
  initialProgram,
}: ReferralDashboardProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const [, startTransition] = useTransition()

  const [selectedClientId, setSelectedClientId] = useState<string>('')
  const [isGenerating, setIsGenerating] = useState(false)
  const [copied, setCopied] = useState<string | null>(null)
  const [singleCodeOpen, setSingleCodeOpen] = useState(false)

  // Program state — updated after save
  const [programData, setProgramData] = useState<ReferralProgramData | null>(initialProgram)
  const programActive = programData?.is_active ?? false

  const handleProgramSaved = useCallback((data: ReferralProgramData) => {
    setProgramData(data)
    startTransition(() => router.refresh())
  }, [router])

  // Code filter from URL
  const codeFilter = (searchParams.get('codes') as CodeFilter | null) ?? 'all'
  const filteredCodes = applyCodeFilter(
    codes.map((c) => ({ ...c, expires_at: c.expires_at ?? null })),
    codeFilter,
  )

  async function handleGenerateCode() {
    if (!selectedClientId) return
    setIsGenerating(true)
    try {
      const res = await fetch('/api/marketing/referrals/codes', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ client_id: selectedClientId }),
      })
      if (!res.ok) {
        const raw: unknown = await res.json()
        const msg =
          raw &&
          typeof raw === 'object' &&
          'error' in raw &&
          typeof (raw as { error: unknown }).error === 'string'
            ? (raw as { error: string }).error
            : `Request failed: ${res.status}`
        throw new Error(msg)
      }
      const json: unknown = await res.json()
      const data =
        json && typeof json === 'object' && 'data' in json
          ? (json as { data: { existing: boolean; code: string } }).data
          : null
      if (data?.existing) {
        toast.success(`Existing code: ${data.code}`)
      } else {
        toast.success('Referral code generated')
      }
      setSelectedClientId('')
      startTransition(() => router.refresh())
    } catch (err) {
      toast.error(err instanceof Error ? err.message : String(err))
    } finally {
      setIsGenerating(false)
    }
  }

  async function handleCopy(text: string) {
    try {
      await navigator.clipboard.writeText(text)
      setCopied(text)
      setTimeout(() => setCopied(null), 1500)
    } catch {
      toast.error('Failed to copy to clipboard')
    }
  }

  const codeIds = filteredCodes.map((c) => c.id)

  return (
    <div className="space-y-5">
      {/* 1. Program rules card — top */}
      {canManage && (
        <ReferralProgramCard
          initialData={initialProgram}
          onSaved={handleProgramSaved}
        />
      )}

      {/* 2. KPI cards */}
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-3">
        <KpiCard
          label="Total codes"
          value={totalReferrals}
          icon={Gift}
          subtextLabel="Active referral codes"
          accentVar="var(--color-rust)"
          index={0}
        />
        <KpiCard
          label="Redemptions"
          value={totalRedemptions}
          icon={Gift}
          subtextLabel="Total uses"
          index={1}
        />
        {/* Top referrers — list, not a counter */}
        <TopReferrersList entries={topReferrers} />
      </div>

      {/* 3. Bulk generate for today — primary CTA */}
      {canManage && (
        <div className="rounded-xl border border-border bg-card shadow-card p-4 space-y-1.5">
          <p className="text-[11px] font-semibold uppercase tracking-[0.08em] text-muted-foreground">
            Bulk generate
          </p>
          <BulkGenerateForToday programActive={programActive} />
        </div>
      )}

      {/* 4. Single-client generate — collapsible disclosure */}
      {canManage && clientOptions.length > 0 && (
        <Collapsible open={singleCodeOpen} onOpenChange={setSingleCodeOpen}>
          <CollapsibleTrigger asChild>
            <button
              type="button"
              className="text-xs text-muted-foreground hover:text-foreground underline underline-offset-2 transition-colors"
            >
              {singleCodeOpen ? 'Hide' : 'Generate for specific client →'}
            </button>
          </CollapsibleTrigger>
          <CollapsibleContent>
            <Card className="shadow-card mt-3">
              <CardHeader className="pb-3">
                <CardTitle className="text-sm font-medium">
                  Generate for specific client
                </CardTitle>
              </CardHeader>
              <CardContent>
                <div className="flex items-center gap-2">
                  <Select
                    value={selectedClientId}
                    onValueChange={(v) => setSelectedClientId(v ?? '')}
                  >
                    <SelectTrigger className="flex-1 h-8 text-xs">
                      <SelectValue placeholder="Select client" />
                    </SelectTrigger>
                    <SelectContent>
                      {clientOptions.map((c) => (
                        <SelectItem key={c.id} value={c.id} className="text-xs">
                          {c.display}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <Button
                    size="sm"
                    disabled={!selectedClientId || isGenerating || !programActive}
                    onClick={handleGenerateCode}
                    className="h-8 text-xs"
                    title={!programActive ? 'Set up your program first →' : undefined}
                  >
                    <Plus className="mr-1.5 h-3.5 w-3.5" aria-hidden="true" />
                    {isGenerating ? 'Generating...' : 'Generate'}
                  </Button>
                </div>
                {!programActive && (
                  <p className="mt-2 text-[11px] text-muted-foreground">
                    Set up your program first →
                  </p>
                )}
              </CardContent>
            </Card>
          </CollapsibleContent>
        </Collapsible>
      )}

      {/* 5. Codes list with filters */}
      <Card className="shadow-card">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm font-medium">Referral codes</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Filter pills + bulk deactivate */}
          <CodesListFilters
            codeIds={codeIds}
            onDeactivated={() => startTransition(() => router.refresh())}
          />

          {filteredCodes.length === 0 ? (
            <EmptyState
              icon={Gift}
              title="No referral codes"
              description={
                codeFilter === 'all'
                  ? 'Generate codes for clients to share with friends.'
                  : `No ${codeFilter.replace('_', ' ')} codes.`
              }
            />
          ) : (
            <ul className="space-y-2">
              {filteredCodes.map((code) => (
                <li
                  key={code.id}
                  className="flex items-center justify-between gap-3 rounded-lg border border-border px-3 py-2"
                >
                  <div className="min-w-0">
                    <div className="flex items-center gap-2 flex-wrap">
                      <code className="text-sm font-mono font-semibold tracking-wider">
                        {code.code}
                      </code>

                      {/* Copy code button */}
                      <button
                        type="button"
                        onClick={() => handleCopy(code.code)}
                        className="text-muted-foreground hover:text-foreground transition-colors"
                        aria-label={`Copy code ${code.code}`}
                      >
                        {copied === code.code ? (
                          <Check className="h-3.5 w-3.5 text-foreground" aria-hidden="true" />
                        ) : (
                          <Copy className="h-3.5 w-3.5" aria-hidden="true" />
                        )}
                      </button>

                      {/* Copy share link */}
                      <button
                        type="button"
                        onClick={() =>
                          handleCopy(`https://inkos.app/book?ref=${code.code}`)
                        }
                        className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
                        aria-label={`Copy share link for code ${code.code}`}
                      >
                        <Clipboard className="h-3 w-3" aria-hidden="true" />
                        {copied === `https://inkos.app/book?ref=${code.code}`
                          ? 'Copied'
                          : 'Share link'}
                      </button>

                      {/* Send via SMS — hidden until SMS wired */}
                      {SMS_WIRED && (
                        <button
                          type="button"
                          className="flex items-center gap-1 text-[11px] text-muted-foreground hover:text-foreground transition-colors"
                          aria-label={`Send code ${code.code} via SMS`}
                        >
                          <MessageSquare className="h-3 w-3" aria-hidden="true" />
                          Send SMS
                        </button>
                      )}

                      {!code.is_active && (
                        <Badge
                          variant="outline"
                          className="text-[11px] text-muted-foreground"
                        >
                          Inactive
                        </Badge>
                      )}
                    </div>

                    {code.client && (
                      <p className="text-xs text-muted-foreground truncate mt-0.5">
                        {code.client.first_name} {code.client.last_name}
                      </p>
                    )}

                    {code.expires_at && (
                      <p className="text-[11px] text-muted-foreground mt-0.5">
                        Expires{' '}
                        {new Date(code.expires_at).toLocaleDateString(undefined, {
                          month: 'short',
                          day: 'numeric',
                          year: 'numeric',
                        })}
                      </p>
                    )}
                  </div>

                  <div className="text-right shrink-0">
                    <p className="text-xs font-medium tabular-nums">
                      {code.discount_type === 'percentage'
                        ? `${code.discount_value}% off`
                        : `$${code.discount_value} off`}
                    </p>
                    <p className="text-xs text-muted-foreground tabular-nums">
                      {code.uses_count}
                      {code.max_uses != null ? `/${code.max_uses}` : ''} uses
                    </p>
                  </div>
                </li>
              ))}
            </ul>
          )}
        </CardContent>
      </Card>
    </div>
  )
}

