import { Card, CardContent, CardHeader } from '@/components/ui/card'

export interface TopReferrerEntry {
  client_id: string
  client_name: string
  redemption_count: number
}

interface TopReferrersListProps {
  entries: TopReferrerEntry[]
}

export function TopReferrersList({ entries }: TopReferrersListProps) {
  return (
    <Card className="shadow-card rounded-xl">
      <CardHeader className="pb-3">
        <span className="text-[11px] font-bold uppercase tracking-[0.08em] text-muted-foreground">
          Top referrers · last 90d
        </span>
      </CardHeader>
      <CardContent>
        {entries.length === 0 ? (
          <p className="text-xs text-muted-foreground">
            No referrers yet — generate codes to start tracking.
          </p>
        ) : (
          <ol className="space-y-2">
            {entries.map((entry, i) => (
              <li
                key={entry.client_id}
                className="flex items-center justify-between gap-3"
              >
                <div className="flex items-center gap-2 min-w-0">
                  <span className="text-[11px] font-bold tabular-nums text-muted-foreground w-4 shrink-0">
                    {i + 1}
                  </span>
                  <span className="text-xs text-foreground truncate">
                    {entry.client_name}
                  </span>
                </div>
                <span className="text-xs font-semibold tabular-nums text-foreground shrink-0">
                  {entry.redemption_count}
                </span>
              </li>
            ))}
          </ol>
        )}
      </CardContent>
    </Card>
  )
}
